(function(root){
'use strict';
function reservations(s){if(root.MaisonShows?.busy(s)||root.MaisonWeeks?.isNight(s))return [];const a=[];const ss=s.music?.session;if(ss)a.push({room:'garage',action:'practice',people:ss.participants,started:ss.started??ss.ends-9,until:ss.ends,songId:ss.songId,kind:ss.kind});const f=s.calendar?.focus;if(f&&f.until>s.tick&&!f.future&&['party','jam','talk'].includes(f.action)&&f.people.length)a.push({room:root.MaisonSim.ACTIONS[f.action].room,action:f.action,people:f.people.filter(id=>{const p=s.people.find(p=>p.id===id);return p&&!(p.playerActionUntil>s.tick&&p.action!==f.action);}),started:f.started??f.until-42,until:f.until});for(const x of s.sharedActivities||[])if(x.until>s.tick&&!a.some(y=>y.room===x.room))a.push(x);return a;}
function register(s,action,ids){if(ids.length<2||!['party','jam','talk','practice'].includes(action))return;const room=root.MaisonSim.ACTIONS[action].room;s.sharedActivities=(s.sharedActivities||[]).filter(x=>x.until>s.tick&&x.room!==room);s.sharedActivities.push({room,action,people:ids,started:s.tick,until:s.tick+9});enforce(s);}
function route(s,p,action,destination){const rs=reservations(s);const own=rs.find(x=>x.people.includes(p.id));if(own&&p.energy>=18&&!(p.playerActionUntil>s.tick&&p.action!==own.action))return {action:own.action,destination:own.action==='party'&&s.people.indexOf(p)%2===1?'kitchen':own.room};const occupied=rs.find(x=>x.room===destination||x.action==='party'&&destination==='kitchen');if(occupied)return {action:'rest',destination:root.MaisonHouse.bedroom(p)};return {action,destination};}
function enforce(s){for(const r of reservations(s)){for(const p of s.people){if(p.room!==r.room&&!(r.action==='party'&&p.room==='kitchen'))continue;if(!r.people.includes(p.id)){p.room=root.MaisonHouse.bedroom(p);p.action='rest';p.travel=4;p.remaining=4;}else if(p.action!==r.action){p.action=r.action;p.remaining=4;}}}}
root.MaisonActivities={reservations,register,route,enforce};if(typeof module!=='undefined')module.exports=root.MaisonActivities;
})(globalThis);
